package org.novasos.healthysv2.pharmacy;
import static org.assertj.core.api.Assertions.*;import java.math.*;import java.time.*;import java.util.*;import org.junit.jupiter.api.Test;
class PrescriptionTests{
 @Test void supportsPartialAndCompleteDispensing(){UUID medication=UUID.randomUUID(),pharmacist=UUID.randomUUID(),pharmacy=UUID.randomUUID();var p=Prescription.create(UUID.randomUUID(),null,UUID.randomUUID(),UUID.randomUUID(),Instant.now().plusSeconds(3600));var item=p.addItem(medication,"500 mg","Twice daily","ORAL","5 days",new BigDecimal("10"),null);p.dispense(pharmacy,pharmacist,List.of(new Prescription.DispenseLine(item.getId(),new BigDecimal("4"),"LOT-1")));assertThat(p.getStatus()).isEqualTo("PARTIALLY_DISPENSED");assertThat(p.dispensed(item.getId())).isEqualByComparingTo("4");p.dispense(pharmacy,pharmacist,List.of(new Prescription.DispenseLine(item.getId(),new BigDecimal("6"),"LOT-1")));assertThat(p.getStatus()).isEqualTo("DISPENSED");assertThatThrownBy(()->p.cancel()).isInstanceOf(IllegalStateException.class);}
 @Test void preventsOverDispensingAndNegativeStock(){var p=Prescription.create(UUID.randomUUID(),null,UUID.randomUUID(),null,null);var item=p.addItem(UUID.randomUUID(),"1 tablet","Daily","ORAL","3 days",new BigDecimal("3"),null);assertThatThrownBy(()->p.dispense(UUID.randomUUID(),UUID.randomUUID(),List.of(new Prescription.DispenseLine(item.getId(),new BigDecimal("4"),"LOT")))).isInstanceOf(IllegalArgumentException.class);var stock=MedicationStock.create(UUID.randomUUID(),UUID.randomUUID(),"LOT",new BigDecimal("2"),LocalDate.now().plusDays(30));assertThatThrownBy(()->stock.consume(new BigDecimal("3"))).isInstanceOf(IllegalStateException.class);}
}
